class Solution {
public:
    string reverseWords(string s) {
        for(int i=0;i<s.size();i++)
        {
            if(s[i]!=' ')
            {
                int j=i;
                for(;j<s.size() and s[j]!=' ';j++) {}
                reverse(s.begin()+i,s.begin()+j);
                i=j-1;
            }
        }
        return s;
    }
};

